using System;
using System.Globalization;
#pragma warning disable IDE0130
namespace PayrollEngine.Client.Scripting.Function;
#pragma warning restore IDE0130

public partial class WageTypeValueFunction
{
    // WT 1250 / WT 5520 — §132(f) commuter transit benefit
    // Apex.TransitBenefitMonthly is the monthly salary-reduction election.
    // Excluded from FIT and FICA up to the monthly limit (lookup US.FederalTaxParameters,
    // key TransitMonthlyLimit); the excess is taxable and withheld after tax.
    // Both parts are converted to the pay period: monthly × 12 / periods per year.
    [ActionParameter("transitField", "CaseField Apex.TransitBenefitMonthly — monthly transit election")]
    [ActionParameter("payFrequencyField", "CaseField US.PayFrequency — Weekly/BiWeekly/SemiMonthly/Monthly")]
    [ActionParameter("lookupName", "Lookup US.FederalTaxParameters with key TransitMonthlyLimit")]
    [WageTypeValueAction("ApexCalculateTransitPreTax",
        "Pre-tax §132(f) transit benefit: monthly election capped at the monthly limit, "
        + "converted to the pay period. Negative value; reduces FIT and FICA taxable wages "
        + "via the WT 1250 extensibility slot. Returns null when no election is set.")]
    public ActionValue ApexCalculateTransitPreTax(string transitField, string payFrequencyField, string lookupName)
    {
        var monthly = GetCaseValue<decimal?>(transitField) ?? 0m;
        if (monthly <= 0m) return null;
        var excluded = Math.Min(monthly, ApexTransitMonthlyLimit(lookupName));
        if (excluded <= 0m) return null;
        return -ApexMonthlyToPeriod(excluded, payFrequencyField);
    }

    [ActionParameter("transitField", "CaseField Apex.TransitBenefitMonthly — monthly transit election")]
    [ActionParameter("payFrequencyField", "CaseField US.PayFrequency — Weekly/BiWeekly/SemiMonthly/Monthly")]
    [ActionParameter("lookupName", "Lookup US.FederalTaxParameters with key TransitMonthlyLimit")]
    [WageTypeValueAction("ApexCalculateTransitExcess",
        "Post-tax part of the transit election above the §132(f) monthly limit, "
        + "converted to the pay period. Negative value. Returns null when the election "
        + "does not exceed the limit.")]
    public ActionValue ApexCalculateTransitExcess(string transitField, string payFrequencyField, string lookupName)
    {
        var monthly = GetCaseValue<decimal?>(transitField) ?? 0m;
        var excess = monthly - ApexTransitMonthlyLimit(lookupName);
        if (monthly <= 0m || excess <= 0m) return null;
        return -ApexMonthlyToPeriod(excess, payFrequencyField);
    }

    private decimal ApexTransitMonthlyLimit(string lookupName)
    {
        var value = GetLookup<string>(lookupName, "TransitMonthlyLimit");
        if (decimal.TryParse(value, NumberStyles.Number, CultureInfo.InvariantCulture, out var limit))
            return limit;
        // without a limit nothing is excluded: the whole election is treated as taxable
        LogWarning($"Apex transit: TransitMonthlyLimit not found in lookup {lookupName}.");
        return 0m;
    }

    private decimal ApexMonthlyToPeriod(decimal monthlyAmount, string payFrequencyField)
    {
        var periods = (GetCaseValue<string>(payFrequencyField) ?? "Monthly") switch
        {
            "Weekly" => 52m,
            "BiWeekly" => 26m,
            "SemiMonthly" => 24m,
            _ => 12m
        };
        return Math.Round(monthlyAmount * 12m / periods, 2, MidpointRounding.AwayFromZero);
    }

    // WT 1260 — WFH Equipment Stipend (Taxable Fringe Benefit)
    // Fully taxable — included in FIT, FICA, SIT, FUTA.
    // No federal or state exclusion applies to a flat WFH stipend
    // (IRC §62(a)(2)(A) accountable plan rules not met for flat payments).
    [ActionParameter("stipendField", "CaseField Apex.WFHStipend — per-period WFH stipend amount")]
    [WageTypeValueAction("ApexCalculateWFHStipend",
        "Returns WFH equipment stipend as taxable gross income. Reads Apex.WFHStipend field directly. "
        + "Returns null when not set or zero. Positive value adds to GrossWages.")]
    public ActionValue ApexCalculateWFHStipend(string stipendField)
    {
        var amount = GetCaseValue<decimal?>(stipendField) ?? 0m;
        if (amount <= 0m) return null;
        return Math.Round(amount, 2);
    }
}
